const first = $json.firstDay;
const last = $json.lastDay;
return [{ json: {
  rangeStart: first + 'T00:00:00',
  rangeEnd: last + 'T23:59:59',
  reason: $json.reason
} }];

// Deterministic pre-step: retrieval + HARD whitelist stay rule-based.
// Drop cancelled + whitelisted events (hard override no AI stage can overrule),
// then emit one item per candidate event for the two AI stages to reason on.
const events = $input.all();
const out = [];
const fmtDay = function (raw) {
  if (!raw) return 'unknown date';
  const d = String(raw).slice(0, 10);
  const parts = d.split('-');
  if (parts.length !== 3) return d;
  return parts[2] + '.' + parts[1] + '.' + parts[0];
};
for (const it of events) {
  const e = it.json || {};
  if (!e.id) continue;
  if (e.isCancelled === true) continue;
  const categories = Array.isArray(e.categories) ? e.categories : [];
  const isWhitelisted = categories.some(function (c) { return String(c).trim().toLowerCase() === 'whitelist'; });
  if (isWhitelisted) continue;
  const attendees = Array.isArray(e.attendees) ? e.attendees : [];
  const startRaw = (e.start && e.start.dateTime) ? e.start.dateTime : '';
  const isRecurring = !!e.recurrence || (e.type && e.type !== 'singleInstance');
  out.push({ json: {
    id: e.id,
    subject: e.subject || '(no subject)',
    isOrganizer: e.isOrganizer === true,
    attendeeCount: attendees.length,
    responseRequested: e.responseRequested === true,
    isRecurring: !!isRecurring,
    day: fmtDay(startRaw),
    start: startRaw ? startRaw.replace('T', ' ').slice(0, 16) : 'unknown time'
  } });
}
return out;

