=Assess whether this single calendar event should be PROTECTED (kept) during an out-of-office period because of its intent / importance. Return json.

Event details:
Subject: {{ $json.subject }}
Am I the organizer: {{ $json.isOrganizer }}
Number of other attendees: {{ $json.attendeeCount }}
Recurring / series event: {{ $json.isRecurring }}
When: {{ $json.day }} {{ $json.start }}

parameters.jsCode:
// Pair the intent AI output (by index) with the candidate list.
// Intent protection is a SOFT override: it only holds when the model is
// confident (>= 0.5). Weak/ambiguous protection is dropped so the event
// falls through to the normal action classification. All items pass on.
const aiItems = $input.all();
const candidates = $('Prefilter Candidates (Deterministic)').all();
const out = [];
for (let i = 0; i < candidates.length; i++) {
  const cand = (candidates[i] && candidates[i].json) || {};
  if (!cand.id) continue;
  const a = (aiItems[i] && aiItems[i].json) || {};
  const parsed = a.output || a;
  const protectedRaw = parsed.protected === true;
  const conf = typeof parsed.confidence === 'number' ? parsed.confidence : 0;
  let label = String(parsed.label || 'none').trim().toLowerCase();
  const validLabels = ['active_contribution', 'relationship_career', 'stay_informed', 'none'];
  if (validLabels.indexOf(label) === -1) label = protectedRaw ? 'active_contribution' : 'none';
  // Effective protection requires a clear signal (confidence >= 0.5).
  const intentProtected = protectedRaw && conf >= 0.5;
  out.push({ json: {
    id: cand.id,
    subject: cand.subject,
    isOrganizer: cand.isOrganizer === true,
    attendeeCount: cand.attendeeCount,
    responseRequested: cand.responseRequested === true,
    isRecurring: cand.isRecurring === true,
    day: cand.day,
    start: cand.start,
    intentProtected: intentProtected,
    intentLabel: intentProtected ? label : 'none',
    intentConfidence: conf,
    intentReason: String(parsed.reason || '')
  } });
}
return out;

