// Combine the two AI stages into one proposal per event.
// Intent protection (soft override) wins: a protected event is proposed as keep,
// regardless of the action model. Otherwise apply the action with the confidence
// fallback (invalid action or confidence < 0.5 -> keep). The raw action decision
// is still recorded so the effect of the intent layer is auditable.
const aiItems = $input.all();
const enriched = $('Apply Intent').all();
const out = [];
for (let i = 0; i < enriched.length; i++) {
  const e = (enriched[i] && enriched[i].json) || {};
  if (!e.id) continue;
  const a = (aiItems[i] && aiItems[i].json) || {};
  const parsed = a.output || a;
  let action = String(parsed.action || '').trim().toLowerCase();
  const confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 1;
  const destructive = (action === 'cancel' || action === 'decline' || action === 'delete');
  if (!destructive || confidence < 0.5) action = 'keep';
  // Intent protection overrides the action to keep.
  const proposed = e.intentProtected === true ? 'keep' : action;
  const proposedSource = e.intentProtected === true ? 'intent' : 'action';
  out.push({ json: {
    id: e.id,
    subject: e.subject,
    day: e.day,
    start: e.start,
    isOrganizer: e.isOrganizer === true,
    attendeeCount: e.attendeeCount,
    responseRequested: e.responseRequested === true,
    isRecurring: e.isRecurring === true,
    intentProtected: e.intentProtected === true,
    intentLabel: e.intentLabel,
    intentConfidence: e.intentConfidence,
    intentReason: e.intentReason,
    aiAction: action,
    aiConfidence: confidence,
    aiReason: String(parsed.reason || ''),
    proposedAction: proposed,
    proposedSource: proposedSource
  } });
}
return out;

// Build the dynamic per-event review form: one dropdown per candidate event,
// pre-selected with the proposed action (intent-protected -> keep), overridable.
const props = $input.all().filter(function (i) { return i.json && i.json.id; });
const rawEvents = $('Get Events In Range').all();
const fmtDay = function (raw) {
  if (!raw) return 'unknown date';
  const d = String(raw).slice(0, 10);
  const parts = d.split('-');
  if (parts.length !== 3) return d;
  return parts[2] + '.' + parts[1] + '.' + parts[0];
};
const fmtTime = function (raw) {
  if (!raw) return '';
  return String(raw).slice(11, 16);
};
// Collect HARD-whitelisted (protected) meetings for the description text.
const whitelisted = [];
for (const it of rawEvents) {
  const e = it.json || {};
  if (!e.id) continue;
  if (e.isCancelled === true) continue;
  const categories = Array.isArray(e.categories) ? e.categories : [];
  const isWhitelisted = categories.some(function (c) { return String(c).trim().toLowerCase() === 'whitelist'; });
  if (!isWhitelisted) continue;
  const startRaw = (e.start && e.start.dateTime) ? e.start.dateTime : '';
  whitelisted.push({ day: fmtDay(startRaw), time: fmtTime(startRaw), subject: e.subject || '(no subject)' });
}
// Per candidate event: one HTML card (two columns: current state vs. AI
// proposal) followed by one short dropdown. The card replaces the long
// dropdown label so the user can tell apart the original event state and
// what the AI suggests at a glance. Dropdown fieldNames stay 'decision_<i>'
// so the logging and execution steps keep working by index.
const esc = function (s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};
const fields = [];
for (let i = 0; i < props.length; i++) {
  const e = props[i].json;
  const isOrganizer = e.isOrganizer === true;
  const options = isOrganizer
    ? [{ option: 'cancel' }, { option: 'keep' }]
    : [{ option: 'decline' }, { option: 'delete' }, { option: 'keep' }];
  const allowed = options.map(function (o) { return o.option; });
  const defaultValue = allowed.indexOf(e.proposedAction) !== -1 ? e.proposedAction : 'keep';
  const actConf = Math.round((typeof e.aiConfidence === 'number' ? e.aiConfidence : 1) * 100);
  const role = isOrganizer ? 'organizer' : 'invited';
  const time = String(e.start || '').slice(11, 16);
  const whenLine = e.day + (time ? ' ' + time : '');
  // Left column: the event as it currently stands (unchanged).
  let left = 'Role: <b>' + esc(role) + '</b><br>';
  left += 'Other attendees: ' + esc(e.attendeeCount) + '<br>';
  left += 'Recurring: ' + (e.isRecurring === true ? 'yes' : 'no') + '<br>';
  left += 'Response requested: ' + (e.responseRequested === true ? 'yes' : 'no') + '<br>';
  left += 'Status: <b>active</b> (currently in calendar)';
  // Right column: what the AI proposes and why.
  let right = 'Proposed action: <b>' + esc(e.proposedAction) + '</b><br>';
  if (e.intentProtected === true) {
    const intConf = Math.round((typeof e.intentConfidence === 'number' ? e.intentConfidence : 0) * 100);
    right += '<span style="color:#0a7d2c;">Protected: ' + esc(e.intentLabel) + ' (' + intConf + '%)</span><br>';
    right += 'Raw action model: ' + esc(e.aiAction) + ' (' + actConf + '%)<br>';
    right += '<i>' + esc(e.intentReason) + '</i>';
  } else {
    right += 'Confidence: ' + actConf + '%<br>';
    right += '<i>' + esc(e.aiReason) + '</i>';
  }
  let card = '<div style="border:1px solid #e2e2e6;border-radius:8px;padding:10px 14px;margin:8px 0 -4px;background:#fbfbfd;">';
  card += '<div style="font-weight:600;font-size:1rem;margin-bottom:8px;">' + esc(whenLine) + ' — ' + esc(e.subject) + '</div>';
  card += '<table style="width:100%;border-collapse:collapse;table-layout:fixed;">';
  card += '<tr>';
  card += '<th style="text-align:left;width:50%;padding:4px 8px;background:#eef1fb;border-bottom:1px solid #ccd;font-size:0.82rem;">Current state</th>';
  card += '<th style="text-align:left;width:50%;padding:4px 8px;background:#e9f7ee;border-bottom:1px solid #cdc;font-size:0.82rem;">AI proposal</th>';
  card += '</tr><tr>';
  card += '<td style="vertical-align:top;padding:6px 8px;font-size:0.9rem;line-height:1.5;">' + left + '</td>';
  card += '<td style="vertical-align:top;padding:6px 8px;font-size:0.9rem;line-height:1.5;">' + right + '</td>';
  card += '</tr></table></div>';
  fields.push({ fieldType: 'html', elementName: 'info_' + i, html: card });
  fields.push({ fieldLabel: 'Your decision — ' + e.subject, fieldName: 'decision_' + i, fieldType: 'dropdown', fieldOptions: { values: options }, defaultValue: defaultValue, requiredField: true });
}
// Description: intro + hard-whitelist list (HTML).
let desc = '<p>For each meeting you see its <b>current state</b> (left) next to the <b>AI proposal</b> (right). Intent-protected meetings are pre-set to <b>keep</b>. Pick an action per meeting, then confirm.</p>';
desc += '<p><b>' + whitelisted.length + '</b> hard-whitelisted meeting(s) are protected and will NOT be changed';
if (whitelisted.length > 0) {
  desc += ':</p><div style="list-style:none;padding:0;margin:0;">';
  for (const w of whitelisted) { desc += '<div>' + w.day + ' — ' + w.subject + '</div>'; }
  desc += '</div>';
} else {
  desc += '.</p>';
}
let noEventsText = '';
if (whitelisted.length === 0) {
  noEventsText = 'No events were determined in the selected time frame.';
} else {
  noEventsText = whitelisted.length + ' determined meeting(s):\n\n';
  const lines = [];
  for (const w of whitelisted) { const when = w.time ? (w.day + ' ' + w.time) : w.day; lines.push(when + ' — ' + w.subject); }
  noEventsText += lines.join('\n');
}
noEventsText += '\n\nYou can close this window.';
return [{ json: { formFieldsJson: JSON.stringify(fields), reviewDescriptionHtml: desc, noEventsText: noEventsText, count: props.length, whitelistedCount: whitelisted.length } }];

// One log row per candidate event: intent decision + action decision + human final.
const cands = $('Classify Proposals').all().filter(function (i) { return i.json && i.json.id; });
const form = $('Review & Approve').first().json || {};
const runId = String($execution.id);
const now = new Date().toISOString();
const out = [];
for (let i = 0; i < cands.length; i++) {
  const e = cands[i].json;
  const human = String(form['decision_' + i] || e.proposedAction).trim().toLowerCase();
  const overridden = human !== e.proposedAction;
  out.push({ json: {
    run_id: runId,
    logged_at: now,
    event_subject: e.subject,
    event_day: e.day,
    intent_protected: e.intentProtected === true,
    intent_label: e.intentLabel,
    intent_confidence: (typeof e.intentConfidence === 'number' ? e.intentConfidence : 0),
    intent_reason: e.intentReason,
    ai_action: e.aiAction,
    ai_confidence: (typeof e.aiConfidence === 'number' ? e.aiConfidence : 1),
    ai_reason: e.aiReason,
    proposed_action: e.proposedAction,
    human_final_action: human,
    was_overridden: overridden
  } });
}
return out;

// Emit one item per event the human wants to act on (cancel/decline/delete).
// 'keep' events are skipped. If nothing is left to execute, emit a sentinel.
const cands = $('Classify Proposals').all().filter(function (i) { return i.json && i.json.id; });
const form = $('Review & Approve').first().json || {};
const out = [];
for (let i = 0; i < cands.length; i++) {
  const e = cands[i].json;
  const action = String(form['decision_' + i] || e.proposedAction).trim().toLowerCase();
  if (action === 'cancel' || action === 'decline' || action === 'delete') {
    out.push({ json: { id: e.id, action: action, subject: e.subject, hasExec: true } });
  }
}
if (out.length === 0) return [{ json: { hasExec: false } }];
return out;
